from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

INSTALLER_VERSION="4.0.1-ALLIANCE-CRE-ACADEMY-MASTERY-REPAIR-INSTALLER"
MODULE_NAME="alliance_cre_academy_v401.py"
REGISTRAR="alliance_optional_property_modules.py"
MODULE_B64=""

def syntax_check(path):
    compile(path.read_text(encoding="utf-8"),str(path),"exec")

def main():
    root=Path.cwd()
    required=["alliance_cre_academy_v400.py","alliance_failure_driven_mastery_v380.py","alliance_optional_property_modules.py"]
    missing=[x for x in required if not (root/x).exists()]
    if missing: raise SystemExit("Missing required cumulative files: "+", ".join(missing))
    registrar=root/REGISTRAR
    original=registrar.read_text(encoding="utf-8")
    stamp=datetime.now().strftime("%Y%m%d-%H%M%S")
    backup=root/f"{REGISTRAR}.before-v401-{stamp}.bak"
    shutil.copy2(registrar,backup)
    (root/MODULE_NAME).write_text(base64.b64decode(MODULE_B64).decode("utf-8"),encoding="utf-8")
    marker="# FOUNDATION 4.0.1 - Alliance CRE Academy Mastery Repair"
    if marker not in original:
        needle="    return result"
        pos=original.rfind(needle)
        if pos<0: raise SystemExit("Final registrar return not found; registrar left unchanged.")
        block=r"""
    # FOUNDATION 4.0.1 - Alliance CRE Academy Mastery Repair
    # Additive repair only. Foundation 4.0, 3.8 and all earlier fixes remain untouched.
    try:
        if _route_exists(app, "/api/property-brain/academy-v401/status"):
            result["academy_v401"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/academy-v401","error":None}
        else:
            import alliance_cre_academy_v401 as academy_v401
            result["academy_v401"] = {**academy_v401.register(core), "error": None}
    except Exception as exc:
        result["academy_v401"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/academy-v401","fail_safe":True}

"""
        registrar.write_text(original[:pos]+block+original[pos:],encoding="utf-8")
    syntax_check(root/MODULE_NAME); syntax_check(registrar)
    reg=registrar.read_text(encoding="utf-8")
    checks={
        "v380":(root/"alliance_failure_driven_mastery_v380.py").exists() and "mastery_v380" in reg,
        "v400":(root/"alliance_cre_academy_v400.py").exists() and "academy_v400" in reg,
        "v401":"academy_v401" in reg
    }
    if not all(checks.values()): raise SystemExit("Cumulative verification failed: "+repr(checks))
    print("Alliance CRE Academy 4.0.1 installed successfully")
    print("Preserved: Foundation 3.8 + 4.0 + all prior registrar content")
    print("Repairs: mixed parent grouping + pre-leased investment ownership + multi-option inventory")
    print("V3 remains retired/unlabeled. V4 only after pre-cert PASS.")
    print("Production/WhatsApp/Gold mutations: 0")
    print("Dashboard: /property-brain/academy-v401")
    print("Backup:",backup)

if __name__=="__main__": main()
